import React, { useState, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import styles from '../css/chat.module.css';

const Chat = () => {
  const location = useLocation();
  const { personality, name: chatbotName = '챗봇' } = location.state || {};
  const [userInput, setUserInput] = useState('');
  const [chatHistory, setChatHistory] = useState([]);
  const [isRecording, setIsRecording] = useState(false); // 녹음 상태 관리
  const [error, setError] = useState(null);
  const chatEndRef = useRef(null);

  const mediaRecorderRef = useRef(null);
  const audioChunksRef = useRef([]);

  // 마이크 녹음 시작
  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      mediaRecorderRef.current = new MediaRecorder(stream);
      
      mediaRecorderRef.current.ondataavailable = event => {
        audioChunksRef.current.push(event.data);
      };

      mediaRecorderRef.current.onstop = () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/mp3' });
        sendAudioToBackend(audioBlob); // 녹음이 끝난 후 서버로 전송
      };

      mediaRecorderRef.current.start();
      setIsRecording(true);
    } catch (err) {
      console.error('Error accessing microphone', err);
      setError('마이크에 접근할 수 없습니다.');
    }
  };

  // 녹음 중지
  const stopRecording = () => {
    if (mediaRecorderRef.current) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  // 음성을 서버로 전송하는 함수
  const sendAudioToBackend = async (audioBlob) => {
    const formData = new FormData();
    formData.append('audio', audioBlob, 'audio.mp3');

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL}/stt`, {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        throw new Error('서버 오류');
      }

      const data = await response.json();
      const transcript = data.transcript; // 백엔드에서 반환한 텍스트
      setUserInput(transcript); // 텍스트로 변환된 음성 결과를 사용자 입력에 설정

      // 텍스트 기반으로 챗봇 응답 받기
      handleSendMessage(transcript);
    } catch (error) {
      console.error('Error sending audio to backend:', error);
      setError('음성을 서버로 전송하는데 실패했습니다.');
    }
  };

  // 메시지 전송
  const handleSendMessage = async (inputText = userInput) => {
    if (inputText.trim() === '') return;

    const sentTime = getTimeOnly();
    const newMessage = { sender: '사용자', message: inputText, time: sentTime };
    setChatHistory((prevHistory) => [...prevHistory, newMessage]);
    setUserInput('');

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL}/chat`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          chatbotName: chatbotName,
          user_input: inputText,
          personality: personality,
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || '오류가 발생했습니다.');
      }

      const data = await response.json();
      const chatbotMessage = data.response;
      const receivedTime = getTimeOnly();
      setChatHistory((prevHistory) => [
        ...prevHistory,
        { sender: chatbotName, message: chatbotMessage, time: receivedTime },
      ]);
    } catch (error) {
      console.error('Error fetching chatbot response:', error);
      setError(error.message);
    }
  };

  // 시:분만 표시하는 함수
  const getTimeOnly = () => {
    const now = new Date();
    const time = now.toLocaleTimeString('ko-KR', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    });
    return time;
  };

  return (
    <div className={styles.chatContainer}>
      <div className={styles.chatHistory}>
        {chatHistory.map((chat, index) => (
          <div key={index} className={chat.sender === '사용자' ? styles.chatMessageUser : styles.chatMessageChatbot}>
            <strong>{chat.sender === '사용자' ? '사용자' : chatbotName}:</strong>
            <div>{chat.message}</div>
            <div className={chat.sender === '사용자' ? styles.chatTimeUser : styles.chatTimeChatbot}>
              <em>{chat.time}</em>
            </div>
          </div>
        ))}
        <div ref={chatEndRef} />
      </div>
      <div className={styles.chatInputArea}>
        <input
          type="text"
          value={userInput}
          onChange={(e) => setUserInput(e.target.value)}
        />
        <button className={styles.chatSendButton} onClick={handleSendMessage}>전송</button>
        <button
          onClick={isRecording ? stopRecording : startRecording}
          className={styles.micButton}
        >
          🎤
        </button>
      </div>
      {error && <div>{error}</div>}
    </div>
  );
};

export default Chat;
